package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.EmailVO;

class EmailValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of email of user")
  void test_email_value_holder_assign_plain_value() {
    Object holder = new Object();
    EmailValueHolder<Object> value = new EmailValueHolder<>(holder);
    Assertions.assertSame(holder, value.email("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getEmailValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getEmail().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.emailNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getEmailValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getEmail().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of email of user")
  void test_email_value_holder_assign_value_object() {
    Object holder = new Object();
    EmailValueHolder<Object> value = new EmailValueHolder<>(holder);
    EmailVO vo = EmailVO.from("one");
    Assertions.assertFalse(value.getEmailValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.email(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getEmailValue().orElseThrow());
    Assertions.assertSame(holder, value.email(Optional.empty()));
    Assertions.assertFalse(value.getEmailValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.email(Optional.of(vo)));
    Assertions.assertSame(vo, value.getEmailValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of email of user against the original")
  void test_email_value_holder_read() {
    Object holder = new Object();
    EmailValueHolder<Object> value = new EmailValueHolder<>(holder);
    EmailVO vo = EmailVO.from("one");
    EmailVO other = EmailVO.from("one");
    User original = Mockito.mock(User.class);
    Mockito.when(original.getEmailValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readEmail(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readEmail(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.email(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readEmail(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readEmail(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of email of user")
  void test_email_value_holder_unset() {
    Object holder = new Object();
    EmailValueHolder<Object> value = new EmailValueHolder<>(holder);
    EmailVO vo = EmailVO.from("one");
    value.email(vo);
    Assertions.assertSame(holder, value.unsetEmailIfMatches("email_other"));
    Assertions.assertTrue(value.getEmailValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetEmailIfMatches("email"));
    Assertions.assertFalse(value.getEmailValue().isPresent(),
        "The field name must clear the value");
    value.email(vo);
    Assertions.assertSame(holder, value.unsetEmail());
    Assertions.assertFalse(value.getEmailValue().isPresent(), "Unset must clear the value");
  }
}
